function replaceTrackedTimeTerminology(value: unknown, replacements: Array<[string, string]> = []): unknown {
  if (typeof value === 'string') return replacements.reduce((copy, [from, to]) => copy.replaceAll(from, to), value);
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value as Translation).map(([key, child]) => [key, replaceTrackedTimeTerminology(child, replacements)]));
  return value;
}

function mergeLocale(base: Translation, additions: LocaleAdditions, locale: AppLocale): Translation {
  const localizedBase = replaceTrackedTimeTerminology(base, trackedTimeTerminology[locale]) as Translation;
  const mergedAdditions: LocaleAdditions = { ...additions, liveActivity: { ...(additions.liveActivity ?? {}), ...liveActivityLayoutCopy[locale] } };
  const keys = new Set([...Object.keys(localizedBase), ...Object.keys(mergedAdditions)]);
  return Object.fromEntries([...keys].map(key => [key, { ...((localizedBase[key] as Record<string, unknown>) ?? {}), ...(mergedAdditions[key as keyof LocaleAdditions] ?? {}) }]));
}

export const translations = Object.fromEntries(Object.entries(baseTranslations).map(([locale, base]) => {
  const merged = mergeLocale(base, localeAdditions[locale as AppLocale], locale as AppLocale);
  const history = merged.history as Translation;
  const reminders = merged.reminders as Translation;
  return [locale, { ...merged, reminders: { ...reminders, title: reminderTitles[locale as AppLocale], longHint: longReminderHints[locale as AppLocale] }, history: { ...history, statuses: { ...(history.statuses as Translation), paused: pausedHistoryLabels[locale as AppLocale] } } }];
})) as unknown as Record<AppLocale, Translation>;

function flattenedKeys(value: Translation, prefix = ''): string[] {
  return Object.entries(value).flatMap(([key, child]) => child && typeof child === 'object' ? flattenedKeys(child as Translation, `${prefix}${key}.`) : [`${prefix}${key}`]);
}

/** Throws during development when a locale drifts from the English key schema. */
export function assertLocaleKeyParity(allTranslations: Record<AppLocale, Translation> = translations) {
  const englishKeys = flattenedKeys(allTranslations.en).sort();
  const failures = (Object.keys(allTranslations) as AppLocale[]).flatMap(locale => {
    const keys = new Set(flattenedKeys(allTranslations[locale]));
    const missing = englishKeys.filter(key => !keys.has(key));
    return missing.length ? [`${locale}: ${missing.join(', ')}`] : [];
  });
  if (failures.length) throw new Error(`i18n key parity failed:\n${failures.join('\n')}`);
}

if (__DEV__) assertLocaleKeyParity();

type Translate = (key: string, options?: Record<string, string | number>) => string;
type I18nContextValue = { locale: AppLocale; languageMode: LanguageMode; setLanguageMode: (mode: LanguageMode) => void; t: Translate };
const I18nContext = createContext<I18nContextValue | null>(null);

export function resolveAppLocale(languageCode: string | null | undefined, regionCode?: string | null, languageTag?: string | null): AppLocale {
  const normalizedLanguageTag = (languageTag ?? languageCode)?.replace(/_/g, '-');
  const language = normalizedLanguageTag?.split('-')[0]?.toLowerCase();
  const region = regionCode?.toUpperCase();
  const hasTraditionalScript = /(^|-)hant(-|$)/i.test(normalizedLanguageTag ?? '');
  if (language === 'zh') return hasTraditionalScript || region === 'TW' || region === 'HK' || region === 'MO' ? 'zh-Hant' : 'zh-CN';
  if (language === 'fr' || language === 'es' || language === 'pt' || language === 'it' || language === 'ru' || language === 'tr' || language === 'id' || language === 'ja' || language === 'ko' || language === 'de') return language === 'pt' ? 'pt-BR' : language;
  return 'en';
}

export function languageModeLabel(mode: LanguageMode, locale: AppLocale) {
  if (mode === 'auto') return languageSettingsCopy(locale).automatic;
  return languageNames[mode];
}

export function languageSettingsCopy(locale: AppLocale) {
  return languageSettingsCopies[locale];
}

