export function I18nProvider({ children }: { children: ReactNode }) {
  const locales = useLocales();
  const [languageMode, setStoredLanguageMode] = useState<LanguageMode>('auto');
  useEffect(() => { AsyncStorage.getItem(LANGUAGE_MODE_KEY).then(value => { if (value === 'zh-CN' || value === 'zh-Hant' || value === 'en' || value === 'fr' || value === 'es' || value === 'pt-BR' || value === 'it' || value === 'ru' || value === 'tr' || value === 'id' || value === 'ja' || value === 'ko' || value === 'de' || value === 'auto') setStoredLanguageMode(value); }).catch(() => undefined); }, []);
  const automaticLocale = resolveAppLocale(locales[0]?.languageCode, locales[0]?.regionCode, locales[0]?.languageTag);
  const locale = languageMode === 'auto' ? automaticLocale : languageMode;
  const setLanguageMode = (mode: LanguageMode) => { setStoredLanguageMode(mode); AsyncStorage.setItem(LANGUAGE_MODE_KEY, mode).catch(() => undefined); };
  const value = useMemo<I18nContextValue>(() => {
    const i18n = new I18n(translations);
    i18n.locale = locale;
    i18n.defaultLocale = 'en';
    i18n.enableFallback = true;
    return { locale, languageMode, setLanguageMode, t: (key, options) => i18n.t(key, options) };
  }, [locale, languageMode]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const value = useContext(I18nContext);
  if (!value) throw new Error('I18nProvider missing');
  return value;
}

export function formatShortTime(ms: number, locale: AppLocale) {
  const minutes = Math.round(ms / 60000);
  const units: Record<AppLocale, { hour: string; minute: string; separator?: string }> = {
    en: { hour: 'h', minute: 'm' }, 'zh-CN': { hour: '小时', minute: '分钟', separator: ' ' }, 'zh-Hant': { hour: '小時', minute: '分鐘', separator: ' ' },
    ja: { hour: '時間', minute: '分', separator: '' }, ko: { hour: '시간', minute: '분', separator: ' ' }, fr: { hour: 'h', minute: 'min', separator: ' ' }, es: { hour: 'h', minute: 'min', separator: ' ' }, 'pt-BR': { hour: 'h', minute: 'min', separator: ' ' }, it: { hour: 'h', minute: 'min', separator: ' ' }, de: { hour: 'Std.', minute: 'Min.', separator: ' ' }, ru: { hour: 'ч', minute: 'мин', separator: ' ' }, tr: { hour: 'sa', minute: 'dk', separator: ' ' }, id: { hour: 'jam', minute: 'mnt', separator: ' ' },
  };
  const { hour, minute, separator = '' } = units[locale];
  if (!minutes) return `0${separator}${minute}`;
  const hours = Math.floor(minutes / 60);
  return hours ? `${hours}${separator}${hour}${minutes % 60 ? ` ${minutes % 60}${separator}${minute}` : ''}` : `${minutes}${separator}${minute}`;
}

export function formatDayLabel(locale: AppLocale, date = new Date()) {
  return new Intl.DateTimeFormat(locale, { weekday: 'long', month: 'long', day: 'numeric' }).format(date);
}

export function formatHistoryDay(locale: AppLocale, day: string) {
  return new Intl.DateTimeFormat(locale, { month: 'long', day: 'numeric', weekday: 'short' }).format(new Date(`${day}T12:00:00`));
}

export function formatWeekday(locale: AppLocale, day: string) {
  return new Intl.DateTimeFormat(locale, { weekday: 'narrow' }).format(new Date(`${day}T12:00:00`));
}
